{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "monthly_trends_heading",
        "intro_text",
        "chart_card",
        "trends_label",
        "trend_1",
        "trend_2",
        "trend_3"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Website Visitor Performance Overview",
        "variant": "h1"
      },
      "children": []
    },
    "monthly_trends_heading": {
      "type": "Text",
      "props": {
        "text": "Monthly Visitor Trends",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "The website has shown a general upward trend in visitor numbers over the past six months, with a slight fluctuation in April.",
        "variant": "body"
      },
      "children": []
    },
    "chart_card": {
      "type": "Card",
      "props": {},
      "children": [
        "visitor_table"
      ]
    },
    "visitor_table": {
      "type": "Table",
      "props": {
        "title": "Monthly Website Visitors",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "Month",
        "highlightColumns": [
          "Visitors"
        ],
        "numericColumns": [
          "Visitors"
        ],
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Visitors",
            "label": "Visitors"
          }
        ],
        "rows": [
          {
            "Month": "January",
            "Visitors": 12000
          },
          {
            "Month": "February",
            "Visitors": 13500
          },
          {
            "Month": "March",
            "Visitors": 14000
          },
          {
            "Month": "April",
            "Visitors": 13800
          },
          {
            "Month": "May",
            "Visitors": 15500
          },
          {
            "Month": "June",
            "Visitors": 16200
          }
        ]
      },
      "children": []
    },
    "trends_label": {
      "type": "Text",
      "props": {
        "text": "Noticed Trends:",
        "variant": "label"
      },
      "children": []
    },
    "trend_1": {
      "type": "Text",
      "props": {
        "text": "Consistent Growth: From January to March, visitors steadily increased.",
        "variant": "body"
      },
      "children": []
    },
    "trend_2": {
      "type": "Text",
      "props": {
        "text": "Minor Dip: A small decrease was observed in April, breaking the growth streak.",
        "variant": "body"
      },
      "children": []
    },
    "trend_3": {
      "type": "Text",
      "props": {
        "text": "Strong Recovery: May saw a significant rebound, reaching a new peak, which continued into June, indicating robust recent growth.",
        "variant": "body"
      },
      "children": []
    }
  }
}
